-- R30 · Sessão do CLIENTE ligada à instância DESCARTÁVEL provada por R20 (só ensaio; NUNCA no staging nem na V1).
-- Corre APENAS através de tools/R40_ligar_cliente.sh, que substitui os marcadores __R_…__ e liga esta sessão ao
-- processo (R41: o processo servidor desta sessão é filho do postmaster provado por R20). Como superutilizador
-- do ensaio, ANTES do bootstrap. Lê o nonce em PGDATA (pg_read_binary_file, só leitura).
-- LIMITE: prova o que a instância e o processo mostram; não prova o anfitrião (precondições E1–E9, REHEARSAL-TARGET.md).
-- Só leitura: um único SELECT. Resultado: uma linha por verificação. Se alguma
-- verificação falhar (ou der NULL), a consulta TERMINA EM ERRO com "REPROVADO: <id> obtido=<valor> | …".
WITH c(id, verificacao, ok, esperado, obtido) AS (
  SELECT 'R30-00'::text, 'marcadores substituídos pelo R40 (caminhos absolutos, números, sha256)'::text, ('__R_PGDATA__' ~ '^/' AND '__R_SOCKDIR__' ~ '^/' AND '__R_SYSID__' ~ '^[0-9]+$' AND '__R_PORT__' ~ '^[0-9]+$' AND '__R_NONCE_SHA256__' ~ '^[0-9a-f]{64}$')::boolean, 'todos'::text, ('ver cabeçalho do ficheiro')::text
  UNION ALL SELECT 'R30-01'::text, 'PostgreSQL 17'::text, (current_setting('server_version_num')::int BETWEEN 170000 AND 179999)::boolean, '17.x'::text, (current_setting('server_version'))::text
  UNION ALL SELECT 'R30-02'::text, 'data_directory = PGDATA provado por R20'::text, (current_setting('data_directory') = '__R_PGDATA__')::boolean, '__R_PGDATA__'::text, (current_setting('data_directory'))::text
  UNION ALL SELECT 'R30-03'::text, 'system identifier = o lido por pg_controldata no R10/R20'::text, ((SELECT system_identifier::text FROM pg_control_system()) = '__R_SYSID__')::boolean, '__R_SYSID__'::text, ((SELECT system_identifier::text FROM pg_control_system()))::text
  UNION ALL SELECT 'R30-04'::text, 'o nonce dentro de PGDATA tem o mesmo sha256 que a cópia FORA de PGDATA'::text, (encode(sha256(pg_read_binary_file('afonso-rehearsal.nonce')), 'hex') = '__R_NONCE_SHA256__')::boolean, '= sha256 da cópia externa'::text, (left(encode(sha256(pg_read_binary_file('afonso-rehearsal.nonce')), 'hex'), 16))::text
  UNION ALL SELECT 'R30-05'::text, 'sem TCP: listen_addresses vazio, definido na linha de comando'::text, (current_setting('listen_addresses') = '' AND (SELECT source FROM pg_settings WHERE name = 'listen_addresses') = 'command line')::boolean, ''''' / command line'::text, ('''' || current_setting('listen_addresses') || ''' / ' || (SELECT source FROM pg_settings WHERE name = 'listen_addresses'))::text
  UNION ALL SELECT 'R30-06'::text, 'socket e porta = os do R10, definidos na linha de comando'::text, (current_setting('unix_socket_directories') = '__R_SOCKDIR__' AND current_setting('port') = '__R_PORT__' AND (SELECT source FROM pg_settings WHERE name = 'unix_socket_directories') = 'command line' AND (SELECT source FROM pg_settings WHERE name = 'port') = 'command line')::boolean, '__R_SOCKDIR__ / __R_PORT__'::text, (current_setting('unix_socket_directories') || ' / ' || current_setting('port') || ' / ' || (SELECT source FROM pg_settings WHERE name = 'port'))::text
  UNION ALL SELECT 'R30-07'::text, 'esta sessão chegou pelo socket local (sem endereço de rede no servidor nem no cliente)'::text, (inet_server_addr() IS NULL AND inet_client_addr() IS NULL)::boolean, 'NULL/NULL'::text, (coalesce(host(inet_server_addr()), 'NULL') || '/' || coalesce(host(inet_client_addr()), 'NULL'))::text
  UNION ALL SELECT 'R30-08'::text, 'nenhuma biblioteca pré-carregada'::text, (current_setting('shared_preload_libraries') = '' AND current_setting('session_preload_libraries') = '' AND current_setting('local_preload_libraries') = '')::boolean, ''''''::text, (current_setting('shared_preload_libraries') || '|' || current_setting('session_preload_libraries') || '|' || current_setting('local_preload_libraries'))::text
  UNION ALL SELECT 'R30-09'::text, 'sem replicação, arquivo nem restauro (nada sai da instância por WAL)'::text, (current_setting('wal_level') = 'minimal' AND current_setting('max_wal_senders') = '0' AND current_setting('archive_mode') = 'off' AND current_setting('archive_command') IN ('', '(disabled)') AND current_setting('archive_library') = '' AND current_setting('restore_command') = '' AND current_setting('primary_conninfo') = '')::boolean, 'minimal/0/off/vazio'::text, (current_setting('wal_level') || '/' || current_setting('max_wal_senders') || '/' || current_setting('archive_mode'))::text
  UNION ALL SELECT 'R30-10'::text, 'ficheiros de configuração = os de PGDATA; nenhum include, nenhum erro, postgresql.auto.conf sem valores (sem ALTER SYSTEM)'::text, (current_setting('config_file') = '__R_PGDATA__/postgresql.conf' AND current_setting('hba_file') = '__R_PGDATA__/pg_hba.conf' AND current_setting('ident_file') = '__R_PGDATA__/pg_ident.conf' AND NOT EXISTS (SELECT 1 FROM pg_file_settings WHERE error IS NOT NULL OR sourcefile IS DISTINCT FROM '__R_PGDATA__/postgresql.conf'))::boolean, 'só postgresql.conf de PGDATA, sem erros'::text, (coalesce((SELECT string_agg(DISTINCT coalesce(sourcefile, 'NULL') || coalesce(' erro=' || error, ''), ',') FROM pg_file_settings), 'nenhuma definição em ficheiro'))::text
  UNION ALL SELECT 'R30-11'::text, 'pg_hba: um só ficheiro, sem erros; só regras local, e host* apenas com reject'::text, (NOT EXISTS (SELECT 1 FROM pg_hba_file_rules WHERE error IS NOT NULL) AND NOT EXISTS (SELECT 1 FROM pg_hba_file_rules WHERE type <> 'local' AND auth_method <> 'reject') AND (SELECT count(DISTINCT file_name) FROM pg_hba_file_rules) = 1 AND NOT EXISTS (SELECT 1 FROM pg_ident_file_mappings))::boolean, 'sim'::text, ((SELECT string_agg(type || ':' || coalesce(auth_method, '?'), ',' ORDER BY rule_number) FROM pg_hba_file_rules))::text
  UNION ALL SELECT 'R30-12'::text, 'nenhuma definição vinda de variáveis de ambiente nem por base/papel (ainda antes do bootstrap)'::text, (NOT EXISTS (SELECT 1 FROM pg_settings WHERE source = 'environment variable') AND NOT EXISTS (SELECT 1 FROM pg_db_role_setting))::boolean, 'nenhuma'::text, (coalesce((SELECT string_agg(name, ',') FROM pg_settings WHERE source = 'environment variable'), '-') || ' / ' || (SELECT count(*) FROM pg_db_role_setting)::text)::text
  UNION ALL SELECT 'R30-13'::text, 'sem SSL, caminho de bibliotecas por omissão'::text, (current_setting('ssl') = 'off' AND current_setting('dynamic_library_path') = '$libdir')::boolean, 'off / $libdir'::text, (current_setting('ssl') || ' / ' || current_setting('dynamic_library_path'))::text
  UNION ALL SELECT 'R30-14'::text, 'nada ligado para fora: só plpgsql instalada; sem servidores externos, subscrições nem slots'::text, ((SELECT array_agg(extname::text ORDER BY extname) FROM pg_extension) = ARRAY['plpgsql'] AND NOT EXISTS (SELECT 1 FROM pg_foreign_server) AND NOT EXISTS (SELECT 1 FROM pg_user_mappings) AND NOT EXISTS (SELECT 1 FROM pg_subscription) AND NOT EXISTS (SELECT 1 FROM pg_replication_slots))::boolean, 'plpgsql / 0 / 0 / 0'::text, ((SELECT string_agg(extname::text, ',') FROM pg_extension) || ' / ' || (SELECT count(*) FROM pg_foreign_server)::text || ' / ' || (SELECT count(*) FROM pg_subscription)::text)::text
  UNION ALL SELECT 'R30-15'::text, 'bases = só as do initdb (e afonso_ensaio, se o bootstrap já correu)'::text, ((SELECT array_agg(datname::text ORDER BY datname) FROM pg_database WHERE datname NOT IN ('afonso_ensaio')) = ARRAY['postgres', 'template0', 'template1'])::boolean, 'postgres,template0,template1'::text, ((SELECT string_agg(datname::text, ',' ORDER BY datname) FROM pg_database))::text
  UNION ALL SELECT 'R30-16'::text, 'sessão do superutilizador do ensaio (ensaio_super) na base postgres; PID do processo servidor desta sessão'::text, (current_user = 'ensaio_super' AND (SELECT rolsuper FROM pg_roles WHERE rolname = current_user) AND current_database() = 'postgres' AND pg_backend_pid() > 0)::boolean, 'ensaio_super / postgres / PID'::text, (current_user::text || ' / ' || current_database()::text || ' / pid ' || pg_backend_pid()::text)::text
),
v AS (SELECT count(*) AS n, string_agg(id || ' obtido=' || left(coalesce(obtido, 'NULL'), 160), ' | ' ORDER BY id) FILTER (WHERE ok IS NOT TRUE) AS falhas FROM c)
SELECT c.id, c.verificacao, CASE WHEN c.ok IS TRUE THEN 'OK' ELSE 'FALHA' END AS estado, c.esperado, c.obtido,
       CASE WHEN v.n <> 17 THEN ('VEREDITO INVÁLIDO: ' || v.n::text || ' verificações')::int::text
            WHEN v.falhas IS NULL THEN 'R30 APROVADO'
            ELSE ('REPROVADO: ' || v.falhas)::int::text END AS veredito
  FROM c CROSS JOIN v ORDER BY c.id;
